('7ab7b445-e346-4c2e-bdb4-4c1c71089994','mz','SSO.IdentityProviders','OIDC/SSO provider config for egov-user (tg, gg). No defaultPassword in data; use env SSO_DEFAULT_PASSWORD_<TENANT>_<PROVIDER>.','{"type":"object","title":"SSO Provider Configuration","$schema":"http://json-schema.org/draft-07/schema#","required":["id","issuerUri"],"x-unique":["id"],"properties":{"id":{"type":"string","minLength":1,"description":"Unique provider identifier (e.g. oidc-azure, oidc-google)"},"ui":{"type":"object","properties":{"logo":{"type":"string"},"name":{"type":"string"},"scopes":{"type":"array","items":{"type":"string"}},"clientId":{"type":"string"},"provider":{"type":"string","description":"Provider identifier used by frontend (e.g. MICROSOFT, GOOGLE)"},"tenantId":{"type":"string","description":"Azure tenant ID used by frontend login"},"authority":{"type":"string","description":"OIDC authority URL used by MSAL"},"authStrategy":{"enum":["MSAL","OIDC_POPUP"],"type":"string"}},"description":"Frontend login button / flow configuration."},"active":{"type":"boolean","description":"When false, provider is skipped entirely. Defaults to true."},"tenantId":{"type":"string","description":"DIGIT tenant this provider belongs to (e.g. tg, gg)"},"userType":{"type":"string","description":"Default DIGIT user type assigned on SSO login (e.g. EMPLOYEE)"},"audiences":{"type":"array","items":{"type":"string"},"description":"Allowed audience (aud) values for token validation"},"issuerUri":{"type":"string","description":"OIDC issuer URL used for token validation"},"jwkSetUri":{"type":"string","description":"JWKS endpoint for signature verification"},"defaultDob":{"type":"integer","description":"Default date-of-birth epoch millis when not available from IdP"},"graphScope":{"type":"string","description":"Scope for MS Graph token request"},"rolePrefix":{"type":"string","description":"Prefix stripped from JWT role values before mapping. Defaults to ''ROLE_''."},"providerType":{"enum":["microsoft","google"],"type":"string","description":"Provider type. Use ''microsoft'' for MS Graph used for validate access token."},"roleClaimKey":{"type":"string","description":"JWT claim key that contains the user''s roles. Defaults to ''roles''."},"roleMappings":{"type":"array","items":{"type":"object","required":["ssoRole","digitRoles"],"properties":{"ssoRole":{"type":"string","minLength":1,"description":"Role name as it appears in the JWT token"},"digitRoles":{"type":"array","items":{"type":"string","minLength":1},"minItems":1,"description":"DIGIT role codes to assign for this SSO role"}}},"description":"Maps SSO provider roles to DIGIT role codes"},"graphClientId":{"type":"string","description":"App registration client ID for MS Graph"},"graphTenantId":{"type":"string","description":"Azure tenant ID for MS Graph token acquisition"},"graphTokenUrl":{"type":"string","description":"Token endpoint for MS Graph client credentials flow"},"graphUsersUrl":{"type":"string","description":"MS Graph endpoint for user profile lookup (e.g. https://graph.microsoft.com/v1.0/users/%s)"},"issuerAliases":{"type":"array","items":{"type":"string"},"description":"Alternate issuer values emitted by this provider (e.g. v1 vs v2 Azure issuer)"},"graphMethodsUrl":{"type":"string","description":"MS Graph endpoint for MFA methods lookup"},"defaultRoleCodes":{"type":"string","description":"Comma-separated DIGIT role codes assigned when no JWT roles match"},"graphServiceType":{"enum":["azure","none"],"type":"string","description":"Graph enrichment service type. Use ''azure'' for MS Graph, ''none'' to skip."},"decryptionPurpose":{"type":"string","description":"MDMS encryption purpose used for decrypting user data. Defaults to UserSelf."},"graphAppResourceId":{"type":"string","description":"Id of app in provider"},"designationClaimKey":{"type":"string","description":"JWT claim key that contains the user''s designation value"},"designationMappings":{"type":"array","items":{"type":"object","required":["idpDesignation","digitDesignationCode"],"properties":{"idpDesignation":{"type":"string","minLength":1,"description":"Designation value as it appears in the JWT token"},"digitDesignationCode":{"type":"string","minLength":1,"description":"DIGIT designation code to assign"}}},"description":"Maps SSO designation claim values to DIGIT designation codes"},"idpUserValidatorType":{"enum":["azure","none"],"type":"string","description":"IdpUserValidator service for checking is user valid or not"},"defaultDepartmentCode":{"type":"string","description":"Default department code for employee creation"},"defaultEmployeeStatus":{"type":"string","description":"Default employment status assigned on user creation. Defaults to EMPLOYED."},"defaultDesignationCode":{"type":"string","description":"Fallback DIGIT designation code when no designationMappings match"},"graphAppRoleAssignmentUrl":{"type":"string","description":"Url to check this user have access to app(e.g. https://graph.microsoft.com/v1.0/users/%s/appRoleAssignments)"},"defaultBoundaryHierarchyType":{"type":"string","description":"Default boundary hierarchy type"}},"description":"Unified config per SSO/OIDC provider — backend JWT validation, MS Graph enrichment, frontend UI, and role mapping."}'::jsonb,true,'uuid','uuid',1777022694594,1777022694594),
